<script setup lang="ts">
definePageMeta({middleware:"auth"}); const route=useRoute(); const {data,refresh}=await useFetch("/api/account/addresses");
async function remove(id:string){ if(!confirm("Hapus alamat ini?"))return; await $fetch(`/api/account/addresses/${id}`,{method:"DELETE"}); await refresh(); }
useSeoMeta({title:"Alamat"});
</script>
<template><section class="container-shell py-12"><div class="flex items-end justify-between"><div><p class="eyebrow">My account</p><h1 class="section-title mt-3">Alamat</h1></div><NuxtLink to="/account/addresses/new" class="rounded-full bg-[#0b4697] px-5 py-3 text-sm font-black text-white">Tambah alamat</NuxtLink></div><div v-if="route.query.created" role="status" class="mt-6 rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm font-bold text-emerald-800">Alamat baru berhasil disimpan dan siap digunakan saat checkout.</div><div class="mt-8 grid gap-4 md:grid-cols-2"><article v-for="address in data?.addresses" :key="(address as any).id" class="surface p-6"><div class="flex justify-between"><h2 class="font-black">{{ (address as any).label }} <span v-if="(address as any).is_default" class="text-xs text-emerald-600">Default</span></h2><button class="text-xs font-bold text-red-600" @click="remove((address as any).id)">Hapus</button></div><p class="mt-3 text-sm"><b>{{ (address as any).recipient_name }}</b> · {{ (address as any).phone }}</p><p class="mt-2 text-sm leading-6 text-slate-500">{{ (address as any).address_line }}, {{ (address as any).subdistrict }}, {{ (address as any).district }}, {{ (address as any).city }} {{ (address as any).postal_code }}</p></article></div></section></template>
